#[path="../../rust/crates/genewars-runtime/src/actor_command.rs"]mod actor;
use actor::*;use std::{env,fs,io::{BufWriter,Write},path::Path};
fn point(b:&[u8],at:usize)->[i16;2]{[i16::from_le_bytes(b[at..at+2].try_into().unwrap()),i16::from_le_bytes(b[at+2..at+4].try_into().unwrap())]}
fn main(){let a:Vec<_>=env::args().collect();let p=Path::new(&a[1]);let mut out=BufWriter::new(fs::File::create(p.join("results.bin")).unwrap());
 for b in fs::read(p.join("setters.bin")).unwrap().chunks_exact(20){let id=i16::from_le_bytes(b[..2].try_into().unwrap());let length=u16::from_le_bytes(b[2..4].try_into().unwrap())as usize;let seed=u32::from_le_bytes(b[4..8].try_into().unwrap())as usize;let prefix=b[11]as usize;let mut bytes:Vec<u8>=(0..prefix+length+11).map(|i|(i*37+seed)as u8).collect();for(offset,value)in[(0x71,b[8]),(0x57,b[9]),(0x82,b[10])]{if offset<length{bytes[prefix+offset]=value;}}let before=bytes.clone();let request=point(b,12);let resolved=point(b,16);let mut echoed=[0;8];let status=match apply_opcode3_move_order(id,&mut bytes[prefix..prefix+length],request,PrecomputedResolvedTarget::new(resolved)){Ok(Opcode3MoveOrderResult::Applied{requested,resolved})=>{for(i,v)in requested.into_iter().chain(resolved).enumerate(){echoed[i*2..i*2+2].copy_from_slice(&v.to_le_bytes());}0},Ok(Opcode3MoveOrderResult::NoopFlag71)=>1,Err(Opcode3MoveOrderError::InvalidActorId(_))=>2,Err(Opcode3MoveOrderError::ActorRecordLength{..})=>3,Err(Opcode3MoveOrderError::ReinitializationRequired{..})=>4};if status!=0{assert_eq!(bytes,before);}out.write_all(&[status]).unwrap();out.write_all(&echoed).unwrap();out.write_all(&bytes).unwrap();}
 for b in fs::read(p.join("resolvers.bin")).unwrap().chunks_exact(15){let current=point(b,0);let request=point(b,4);let env=ResolverEnvironment{terrain_class:b[8],actor_avoidance_mask:b[9],obstacle_present:b[10]!=0,blocker_weight:i32::from_le_bytes(b[11..15].try_into().unwrap())};let mut answer=[0;4];let status=match resolve_bounded_move_target(current,request,env){Ok(r)=>{for(i,v)in r.position().into_iter().enumerate(){answer[i*2..i*2+2].copy_from_slice(&v.to_le_bytes());}0},Err(ResolverError::InvalidTerrainClass(_))=>1,Err(ResolverError::NegativeBlockerWeight(_))=>2,Err(ResolverError::BackwardSearchRequired)=>3};out.write_all(&[status]).unwrap();out.write_all(&answer).unwrap();}
 out.flush().unwrap();}
